def buildInspectionDays(max_products, tasks):
    lo = hi = 0  # range of reachable stock levels
    days = 0
    for t in tasks:
        if t != 0:
            lo += t
            hi = min(hi + t, max_products)
            if lo > max_products:
                return -1
        elif hi < 0:
            days += 1
            lo, hi = 0, max_products
        else:
            lo = max(lo, 0)
    return days
